L5 = Lesson("1.5", "The Five Vowel Sounds",
    "I can pronounce the five Spanish vowels clearly.", "ACTFL Novice · Presentational",
    [("vocal", "vowel")],
    "English vowels make many sounds (think of the a in cat, cake, and car). How many sounds do you think Spanish vowels make?",
    [Text("Good news: each Spanish vowel makes just <b>one</b> short, clear sound. Learn these five and you can read almost any Spanish word aloud."),
     Phrases("Las vocales", [("a", "ah (as in father)", "casa (KAH-sah) house"), ("e", "eh (as in met)", "mesa (MEH-sah) table"), ("i", "ee (as in see)", "sí (see) yes"),
                             ("o", "oh (short, as in no)", "oso (OH-soh) bear"), ("u", "oo (as in food)", "uno (OO-noh) one")]),
     Example("Read new words", "Read aloud: mamá, papá, piso, luna, Pepe",
             ["Say each vowel with its one sound.", "mah-MAH, pah-PAH, PEE-soh, LOO-nah, PEH-peh"], "If you know the vowels, you can sound out words you've never seen."),
     Callout("CANCIÓN", "Sing “A, E, I, O, U, el burro sabe más que tú” (“the donkey knows more than you”), a vowel song many Spanish-speaking children learn. Search the title to hear it."),
     KeyIdea("a = ah, e = eh, i = ee, o = oh, u = oo, always.")],
    [Problem("Sound of e", "eh"), Problem("Sound of i", "ee"), Problem("Read aloud: luna", "LOO-nah")],
    [S("Calentamiento", [SA("Thank you =", "Gracias"), SA("You're welcome =", "De nada")], cols=2),
     S("Practica", [SA(q, a) for q, a in [("Which vowel sounds like “ee”?", "i"), ("Which vowel sounds like “oo”?", "u"), ("Sound out: mesa", "MEH-sah"), ("Sound out: piso", "PEE-soh"),
                                          ("Sound out: Lupe", "LOO-peh")]], cols=1),
     S("Escucha", [LISTEN("Write the vowel you hear.", "a … i … u … e … o", "a, i, u, e, o")])],
    tsp("Students pronounce the five vowels.", "Presentational speaking: pronunciation.", "Workbook Lesson 1.5",
        "English vowel sounds.", "Model each vowel with mouth shape; choral repetition.", "Read new words.", "Practica; vowel song.",
        ["Saying e like English ee, or u like you."], ["Mirror practice for mouth shapes."], ["Find five Spanish words on food packages and read them aloud."]),
    summary="Each Spanish vowel has one clear sound.")

L6 = Lesson("1.6", "The Spanish Alphabet",
    "I can say the Spanish alphabet and recognize letters with special sounds.", "ACTFL Novice · Interpretive",
    [("el alfabeto", "the alphabet"), ("la letra", "the letter")],
    "Do you think Spanish has more letters, fewer, or the same number as English?",
    [Text("The Spanish alphabet has <b>27 letters</b>: the same 26 as English plus <b>ñ</b>. Some letters sound different from English."),
     Figure(lambda t: table(t, [["Letter", "Name", "Sound tip"], ["h", "hache (AH-cheh)", "always silent: hola"], ["j", "jota (HOH-tah)", "like a strong English h: jugo (HOO-goh)"],
                                ["ll (two letters)", "doble ele", "like y in yes: llamo"], ["ñ", "eñe (EH-nyeh)", "like ny in canyon: mañana"], ["rr (two letters)", "doble erre", "rolled r: perro (PEH-rroh)"],
                                ["v", "uve or ve (OO-veh / veh)", "sounds almost like b: vaca"], ["z", "zeta (SEH-tah)", "like s in Latin America: zapato"]],
                            [1.3 * inch, 1.8 * inch, 2.6 * inch], width=5.7 * inch, font_size=9.5)),
     Text("The other letter names are close to English: a (ah), be (beh), ce (seh), de (deh), e (eh), efe (EH-feh), ge (heh), i (ee), ka (kah), ele (EH-leh), eme (EH-meh), ene (EH-neh), o (oh), pe (peh), cu (koo), erre (EH-rreh), ese (EH-seh), te (teh), u (oo), doble uve (DOH-bleh OO-veh), equis (EH-kees), ye (yeh)."),
     AUDIO,
     KeyIdea("27 letters, including ñ. Watch for h (silent), j (strong h), ll (y), ñ (ny), and rr (rolled).")],
    [Problem("How many letters in the Spanish alphabet?", "27"), Problem("What sound does ñ make?", "ny, as in canyon"), Problem("Which letter is silent?", "h")],
    [S("Calentamiento", [SA("Sound of a", "ah"), SA("Sound of u", "oo")], cols=2),
     S("Practica", [SA(q, a) for q, a in [("Name of the letter j", "jota"), ("Name of the letter ñ", "eñe"), ("Sound of ll in llama", "y"), ("Say: perro (dog)", "PEH-rroh, with a rolled r"),
                                          ("Say: jirafa (giraffe)", "hee-RAH-fah")]], cols=1),
     S("Escucha", [LISTEN("Circle the letter you hear.", "eñe", None, choices=["n", "ñ", "ll"], correct=1)])],
    tsp("Students learn the alphabet and special letters.", "Interpretive: sound-letter correspondence.", "Workbook Lesson 1.6",
        "Guess the letter count.", "Sing or chant the alphabet; drill special letters.", "Special letters table.", "Practica.",
        ["Pronouncing h and j like English."], ["Alphabet chart on the fridge."], ["Practice rolling r with “erre con erre cigarro” tongue twister."]),
    summary="27 letters, with special h, j, ll, ñ, rr.")

L7 = Lesson("1.7", "Accent Marks and Upside-Down Punctuation",
    "I can explain what accent marks and ¿ ¡ do and use them when I write.", "ACTFL Novice · Presentational",
    [("acento", "accent mark (´), which shows the stressed syllable"), ("signos de interrogación", "question marks: ¿ ?"), ("signos de exclamación", "exclamation marks: ¡ !")],
    "Look at this: ¿Cómo estás? What do you notice that English doesn't do?",
    [Text("Spanish puts an upside-down question mark <b>¿</b> at the start of a question and an upside-down exclamation mark <b>¡</b> at the start of an exclamation, so readers know right away how to read the sentence."),
     Text("An <b>accent mark</b> (´) shows which part of the word to say louder: <b>adiós</b> (ah-DYOHS), <b>mamá</b> (mah-MAH). Sometimes an accent changes the meaning: <b>sí</b> means yes, but <b>si</b> means if; <b>tú</b> means you, but <b>tu</b> means your."),
     Example("Write it correctly", "Fix: hola como estas", ["Start the exclamation with ¡ and end with !: ¡Hola!", "Start the question with ¿ and end with ?.", "Add accents: Cómo, estás."], "¡Hola! ¿Cómo estás?"),
     KeyIdea("¿…? and ¡…! wrap questions and exclamations. Accent marks show stress and can change meaning.")],
    [Problem("Fix: como te llamas?", "¿Cómo te llamas?"), Problem("Meaning of sí", "yes"), Problem("Where does ¡ go?", "at the start of an exclamation")],
    [S("Calentamiento", [SA("Name of ñ", "eñe"), SA("Is h silent?", "sí")], cols=2),
     S("Practica", [SA(q, a) for q, a in [("Fix: hola", "¡Hola!"), ("Fix: como estas", "¿Cómo estás?"), ("Fix: adios", "¡Adiós!"), ("Meaning of tú", "you"), ("Meaning of si (no accent)", "if")]], cols=1),
     S("Escribe", [OR("Write a question and an exclamation from this unit with correct punctuation.", "e.g. ¿Cómo te llamas? ¡Hasta luego!", lines=2)])],
    tsp("Students use Spanish punctuation and accents.", "Presentational writing conventions.", "Workbook Lesson 1.7",
        "Spot the difference in ¿Cómo estás?", "Read accented words, stressing the marked syllable.", "Model fixing sentences.", "Practica.",
        ["Putting ¿ at the end."], ["Highlight ¿ and ? in matching colors."], ["Type ñ and accents on a keyboard or tablet."]),
    summary="¿Questions? ¡Exclamations! Accents show stress.")

