    tsp("Students distinguish tú and usted.", "Interpersonal; cultural practices of respect.", "Workbook Lesson 1.11",
        "Talking to friends vs doctors.", "Model both forms.", "Tú/usted chart.", "Practica.",
        ["Using tú with every adult."], ["Sort cards: people → tú or usted."], ["Greet an adult Spanish speaker politely (store, church, neighbor)."]),
